import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';
import type { JxBadgeTone } from '@jinx-ui/react';

type ProjectStatus = 'active' | 'pending' | 'over' | 'closed';

interface Project {
  id: string;
  name: string;
  quotaUsed: number;
  quotaTotal: number;
  status: ProjectStatus;
}

const STATUS_CONFIG: Record<ProjectStatus, { label: string; tone: JxBadgeTone }> = {
  active: { label: 'Активен', tone: 'success' },
  pending: { label: 'Ожидает', tone: 'warning' },
  over: { label: 'Превышен', tone: 'danger' },
  closed: { label: 'Закрыт', tone: 'alt' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Атлас маркетинга', quotaUsed: 42, quotaTotal: 100, status: 'active' },
  { id: 'p2', name: 'Редизайн кабинета', quotaUsed: 96, quotaTotal: 100, status: 'over' },
  { id: 'p3', name: 'Миграция биллинга', quotaUsed: 10, quotaTotal: 100, status: 'pending' },
  { id: 'p4', name: 'Мобильное приложение', quotaUsed: 68, quotaTotal: 100, status: 'active' },
  { id: 'p5', name: 'Аналитика продаж', quotaUsed: 100, quotaTotal: 100, status: 'closed' },
  { id: 'p6', name: 'Портал партнёров', quotaUsed: 55, quotaTotal: 100, status: 'active' },
  { id: 'p7', name: 'Внутренний CRM', quotaUsed: 88, quotaTotal: 100, status: 'over' },
  { id: 'p8', name: 'Обновление API', quotaUsed: 5, quotaTotal: 100, status: 'pending' },
  { id: 'p9', name: 'Каталог продуктов', quotaUsed: 30, quotaTotal: 100, status: 'closed' },
  { id: 'p10', name: 'Служба поддержки', quotaUsed: 74, quotaTotal: 100, status: 'active' },
  { id: 'p11', name: 'Логистика склада', quotaUsed: 20, quotaTotal: 100, status: 'pending' },
  { id: 'p12', name: 'Финансовый отчёт', quotaUsed: 99, quotaTotal: 100, status: 'over' },
];

const STATUS_ORDER: ProjectStatus[] = ['active', 'pending', 'over', 'closed'];
const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([]);
    setPage(1);
  };

  const filteredProjects = useMemo(() => {
    if (activeStatuses.length === 0) return PROJECTS;
    return PROJECTS.filter((p) => activeStatuses.includes(p.status));
  }, [activeStatuses]);

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const visibleProjects = filteredProjects.slice(
    (page - 1) * PAGE_SIZE,
    page * PAGE_SIZE
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        maxWidth: '640px',
      }}
    >
      <div>
        <h2
          style={{
            margin: 0,
            marginBottom: '4px',
            color: 'var(--jx-text)',
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
          }}
        >
          Расход по проектам
        </h2>
        <p style={{ margin: 0, color: 'var(--jx-text-3)', fontSize: '14px' }}>
          Заполненность квоты по каждому проекту
        </p>
      </div>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUS_ORDER.map((status) => {
          const active = activeStatuses.includes(status);
          return (
            <JxChip
              key={status}
              active={active}
              removable={active}
              onClick={() => toggleStatus(status)}
              onRemove={() => toggleStatus(status)}
            >
              {STATUS_CONFIG[status].label}
            </JxChip>
          );
        })}
      </div>

      {visibleProjects.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="По выбранным статусам нет проектов. Сбросьте фильтры, чтобы увидеть весь список."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visibleProjects.map((project) => {
              const percent = Math.round((project.quotaUsed / project.quotaTotal) * 100);
              const config = STATUS_CONFIG[project.status];
              return (
                <div
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: '16px',
                    padding: '12px 8px',
                    borderBottom: '1px solid var(--jx-rule)',
                  }}
                >
                  <span
                    style={{
                      color: 'var(--jx-text)',
                      fontSize: '15px',
                      flex: 1,
                      minWidth: 0,
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                    }}
                  >
                    {project.name}
                  </span>
                  <JxProgressCircle value={percent} showValue />
                  <JxBadge tone={config.tone} dot>
                    {config.label}
                  </JxBadge>
                </div>
              );
            })}
          </div>

          {pageCount > 1 && (
            <div style={{ display: 'flex', justifyContent: 'center' }}>
              <JxPagination total={pageCount} page={page} onPageChange={setPage} />
            </div>
          )}
        </>
      )}
    </div>
  );
}

